/// One ring: radius and width x 10, the mask's side, its top-left from the centre, and per pixel coverage and angle.
pub struct RingMask {
    pub r10: u16,
    pub w10: u16,
    pub size: u8,
    pub off: i8,
    pub cov: &'static [u8],
    pub ang: &'static [u8],
}

/// The mask for a ring of radius `r` and width `w`, if one was generated.
pub fn find(r: f32, w: f32) -> Option<&'static RingMask> {
    let (r10, w10) = ((r * 10.0 + 0.5) as u16, (w * 10.0 + 0.5) as u16);
    RINGS.iter().find(|m| m.r10 == r10 && m.w10 == w10)
}

